SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "朱祁镇", "aliases": ["明英宗"], "era": "明", "birth_year": null, "death_year": null, "description": "明英宗，宣德10年（1435年）正月，朱祁镇即皇帝位。", "biography": null, "status": "draft", "id": "368e5a42-621f-5c8c-88c7-f59b8bb8a5cf"}, {"name": "颜彪", "aliases": ["顏彪"], "era": "明", "birth_year": null, "death_year": null, "description": "颜彪任总兵官并奉命征讨。", "biography": null, "status": "draft", "id": "c11dccdb-cf15-5675-9f5c-217849283830"}, {"name": "李震（明代湖广总兵）", "aliases": ["總兵官李震"], "era": "明", "birth_year": null, "death_year": null, "description": "李震（明代湖广总兵）率部会同广西军队作战。", "biography": null, "status": "draft", "id": "e1ba4ff9-a404-5a85-a6d0-056f2166ce66"}, {"name": "白圭（明代官员）", "aliases": [], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，天顺7年（年号对照1463年）三月，白圭出任工部尚书。", "biography": null, "status": "draft", "id": "35318e39-4ec3-528e-a5b4-28cd8d9c4c65"}, {"name": "孛来", "aliases": ["孛來"], "era": "明", "birth_year": null, "death_year": null, "description": "孛来率部进攻宁夏。", "biography": null, "status": "draft", "id": "002b89e8-be8d-5e7f-9365-e517b45d0c6d"}, {"name": "马昂", "aliases": ["馬昂"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，天顺元年（年号对照1457年）五月，马昂出任都察院长官，外出巡抚山西。", "biography": null, "status": "draft", "id": "4c756f57-201a-5770-b7a5-670042269b3e"}, {"name": "孙镗（明代怀宁侯）", "aliases": ["都督孫鏜"], "era": "明", "birth_year": null, "death_year": null, "description": "孙镗（明代怀宁侯）奉命协守大同。", "biography": null, "status": "draft", "id": "398dbeeb-49de-5e59-83a3-d34743d70b6e"}, {"name": "曹吉祥", "aliases": ["太監曹吉祥"], "era": "明", "birth_year": null, "death_year": null, "description": "曹吉祥参与节制团营。", "biography": null, "status": "draft", "id": "317dfea3-6884-5ef9-82ae-6040eb5025fe"}, {"name": "曹钦", "aliases": [], "era": "明", "birth_year": null, "death_year": null, "description": "明代起兵者。天顺5年（年号对照1461年），本表记录了曹钦的活动。", "biography": null, "status": "draft", "id": "4667ba2d-c9e8-5b4f-8a95-cb0080e144eb"}, {"name": "寇深", "aliases": [], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，天顺元年（年号对照1457年）七月，寇深出任都察院长官。", "biography": null, "status": "draft", "id": "6eb8a375-30ed-5fe5-9274-e82a3380be1d"}, {"name": "冯宗", "aliases": ["都督馮宗"], "era": "明", "birth_year": null, "death_year": null, "description": "冯宗任总兵官并奉命防守河西。", "biography": null, "status": "draft", "id": "ea5e1807-807f-5330-bbfd-4c090775b9ae"}, {"name": "王竑", "aliases": [], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，天顺8年（年号对照1464年）八月，王竑出任兵部尚书。", "biography": null, "status": "draft", "id": "8205d462-b054-532d-b98c-31861dd69b39"}]'::jsonb)
