INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "明英宗在南郊祭祀天地", "description": "天顺五年正月庚戌，明英宗朱祁镇在南郊举行祭祀天地的大典。", "start_year": 1461, "end_year": 1461, "time_original": "天顺五年正月庚戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "49aad18e-13c2-50b4-8199-53e6987d3413"}, {"title": "明廷豁免山东灾区税粮", "description": "天顺五年二月己卯，朝廷免除山东受灾地区应缴的税粮。", "start_year": 1461, "end_year": 1461, "time_original": "天顺五年二月己卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "34fdc353-fbc6-57cc-ab2a-00a42d93bac3"}, {"title": "颜彪受命领兵征讨两广起事瑶民", "description": "天顺五年二月丙申，明廷任命都督佥事颜彪为征夷将军、总兵官，令他率军征讨两广起事的瑶民。", "start_year": 1461, "end_year": 1461, "time_original": "天顺五年二月丙申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "95679aac-75aa-5f70-b882-b5abb6205b0c"}, {"title": "明廷豁免苏松常镇灾区税粮", "description": "天顺五年三月壬子，朝廷免除苏州、松江、常州、镇江受灾地区应缴的税粮。", "start_year": 1461, "end_year": 1461, "time_original": "天顺五年三月壬子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a9e97728-92e2-5d50-8162-9d1ff62d1fda"}, {"title": "李震与广西军队会合，击败当地起事武装", "description": "天顺五年三月甲寅，湖广、贵州总兵官李震会同广西军队，击败原文称为“瑶、僮”的起事武装。", "start_year": 1461, "end_year": 1461, "time_original": "天顺五年三月甲寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2cf6ae42-6e4d-5391-b65b-cd6320635706"}, {"title": "白圭督办陕西边防，奉命征讨孛来", "description": "天顺五年四月癸巳，朝廷派兵部侍郎白圭督办陕西各处边防，征讨孛来所部。", "start_year": 1461, "end_year": 1461, "time_original": "天顺五年四月癸巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "fb36b2ce-c7bb-5388-83a1-5ebefb7bb50f"}, {"title": "明廷豁免河南灾区秋粮", "description": "天顺五年五月丁未，朝廷免除河南受灾地区应缴的秋粮。", "start_year": 1461, "end_year": 1461, "time_original": "天顺五年五月丁未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "1a25a0c6-4561-5774-86b5-d3ef7ee96ee6"}, {"title": "孛来进攻河西，明军战败", "description": "天顺五年六月丙子，孛来所部进攻河西，驻守的明军在交战中失利。", "start_year": 1461, "end_year": 1461, "time_original": "天顺五年六月丙子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "8e8c952a-0946-52b6-99a9-a24419f89508"}, {"title": "马昂总督军务，孙镗率京营兵赴河西抵御", "description": "天顺五年六月壬午，明廷派兵部尚书马昂总督军务，任命怀宁伯孙镗为总兵官，率京营兵力抵御入侵河西的孛来所部。", "start_year": 1461, "end_year": 1461, "time_original": "天顺五年六月壬午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "810b6b3f-3d6a-565f-a0e8-88b886e5d45c"}, {"title": "曹钦发动叛乱", "description": "天顺5年（年号对照1461年）七月，曹钦发动叛乱。", "start_year": 1461, "end_year": 1461, "time_original": "天顺5年（年号对照1461年）七月；公元年核为1461年。", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "764f63ec-86b9-5f77-b259-38e4491fa682"}, {"title": "寇深在曹钦发动的叛乱中被杀", "description": "天顺5年（年号对照1461年）七月，寇深在曹钦发动的叛乱中被杀。", "start_year": 1461, "end_year": 1461, "time_original": "天顺5年（年号对照1461年）七月；公元年核为1461年。", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "832c6eaa-f772-5631-915d-2fc18bf1fe48"}, {"title": "明廷处死曹吉祥及汤序等人", "description": "天顺五年七月癸卯，朝廷处死曹吉祥，其族人受牵连被处死，汤序等也被处死。", "start_year": 1461, "end_year": 1461, "time_original": "天顺五年七月癸卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "8f6eb4e1-6a5f-5252-a76d-51884d3b8bd1"}, {"title": "明廷豁免南直隶灾区税粮", "description": "天顺五年七月丁未，朝廷免除南直隶受灾地区应缴的税粮。", "start_year": 1461, "end_year": 1461, "time_original": "天顺五年七月丁未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b609931a-2348-5ffd-891f-e3d30abbd65a"}, {"title": "明廷大赦天下，征求直言", "description": "天顺五年七月庚戌，明廷颁布大赦，并请臣下直言政事。", "start_year": 1461, "end_year": 1461, "time_original": "天顺五年七月庚戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "6a6ba2ec-6fd4-5213-acbf-c43f734e113a"}, {"title": "黄河在开封决口，薛远奉命治理", "description": "天顺五年七月丁巳，黄河在开封决口，朝廷派侍郎薛远前往治理。", "start_year": 1461, "end_year": 1461, "time_original": "天顺五年七月丁巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "9739716b-afe3-5cf3-bb42-b96ca8409464"}, {"title": "冯宗领兵防守河西，白圭、王竑参赞军务", "description": "天顺五年七月戊午，朝廷任都督冯宗为总兵官，到河西抵御来犯部队，命兵部侍郎白圭与副都御史王竑参赞军务。", "start_year": 1461, "end_year": 1461, "time_original": "天顺五年七月戊午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a820eeac-f295-5dac-9cea-9ad59dbe9f79"}, {"title": "孛来上书明廷请求议和", "description": "天顺五年七月辛酉，孛来上书明廷，请求议和。", "start_year": 1461, "end_year": 1461, "time_original": "天顺五年七月辛酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "f8750b52-bb73-5c33-b3db-a392fc5d51ed"}, {"title": "京师发生地震，并伴有声响", "description": "天顺五年九月壬戌，《明史》本纪记京师发生地震并伴有声响。", "start_year": 1461, "end_year": 1461, "time_original": "天顺五年九月壬戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7276dc52-14ff-55b1-811f-f0a573b2c839"}, {"title": "明廷准河南、山西、陕西士民交纳马匹换取冠带", "description": "天顺五年十月壬申，因西部边境用兵，朝廷下令河南、山西、陕西的士民交纳马匹者可获冠带。", "start_year": 1461, "end_year": 1461, "time_original": "天顺五年十月壬申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e14cd716-c478-5fcd-afbc-18868e845b5f"}, {"title": "本纪记天顺五年十一月初一发生日食", "description": "天顺五年十一月初一，《英宗后纪》记发生日食。", "start_year": 1461, "end_year": 1461, "time_original": "天顺五年十一月丁酉朔", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "5764fae6-beb6-5f49-a378-c0523e9135c2"}, {"title": "明英宗前往南海子", "description": "天顺五年十一月壬戌，明英宗朱祁镇前往南海子。", "start_year": 1462, "end_year": 1462, "time_original": "天顺五年十一月壬戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "f212e240-9e24-538d-999b-a629468a9117"}, {"title": "安南、琉球中山、哈密和亦力把里入贡", "description": "天顺五年，安南、琉球中山、哈密和亦力把里入贡。 按原历纪年，事情发生在公元1461至1462年之间。", "start_year": null, "end_year": null, "time_original": "天顺五年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d7d8a92c-f627-53eb-9640-b24bbb4c07ad"}]'::jsonb)
